END $guard$;
DO $install$
DECLARE grant_row record; proc_oid oid;
BEGIN
IF to_regprocedure('public._soe_circle_profile_message(uuid,jsonb)') IS NULL THEN EXECUTE $ddl$CREATE FUNCTION public._soe_circle_profile_message(p_circle_id uuid,p_message jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $body$
DECLARE ref uuid;
BEGIN
 IF p_message IS NULL OR jsonb_typeof(p_message)<>'object' THEN RAISE EXCEPTION USING ERRCODE='PT503',MESSAGE='Profile reference unavailable'; END IF;
 IF p_message->>'visibility'='visible' THEN
  SELECT m.member_id INTO ref FROM public.seminar_messages m
   JOIN public.book_cohorts c ON c.id=m.cohort_id
   JOIN public.members author ON author.id=m.member_id AND author.profile_visibility='public'
   LEFT JOIN public.circle_message_states s ON s.message_id=m.id
   WHERE m.cohort_id=p_circle_id AND m.id=(p_message->>'id')::uuid AND c.book_id='soe-circles-path' AND NOT c.circle_hidden
    AND NOT coalesce(s.hidden,false) AND NOT coalesce(s.withdrawn,false)
    AND public._soe_circle_discussion_available(m.content,m.created_at);
 END IF;
 RETURN p_message || jsonb_build_object('publicProfileId',ref);
END
$body$$ddl$; COMMENT ON FUNCTION public._soe_circle_profile_message(uuid,jsonb) IS 'soe-circle-public-profiles:v1:owned'; END IF;
proc_oid:='public._soe_circle_profile_message(uuid,jsonb)'::regprocedure;
FOR grant_row IN SELECT DISTINCT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=proc_oid AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',proc_oid::regprocedure,CASE WHEN grant_row.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(grant_row.grantee)) END); END LOOP;
GRANT EXECUTE ON FUNCTION public._soe_circle_profile_message(uuid,jsonb) TO service_role;
IF to_regprocedure('public._soe_circle_profile_page(uuid,jsonb)') IS NULL THEN EXECUTE $ddl$CREATE FUNCTION public._soe_circle_profile_page(p_circle_id uuid,p_page jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $body$
DECLARE key text; item jsonb; items jsonb;
BEGIN
 IF p_page IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_page)<>'object' THEN RAISE EXCEPTION USING ERRCODE='PT503',MESSAGE='Profile references unavailable'; END IF;
 FOREACH key IN ARRAY ARRAY['messages','items'] LOOP
  IF p_page ? key THEN
   IF jsonb_typeof(p_page->key)<>'array' OR jsonb_array_length(p_page->key)>100 THEN RAISE EXCEPTION USING ERRCODE='PT503',MESSAGE='Profile references unavailable'; END IF;
   items:='[]'::jsonb;
   FOR item IN SELECT value FROM jsonb_array_elements(p_page->key) LOOP
    items:=items || jsonb_build_array(public._soe_circle_profile_message(p_circle_id,item));
   END LOOP;
   p_page:=jsonb_set(p_page,ARRAY[key],items);
  END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['root','focus','message'] LOOP
  IF p_page ? key THEN p_page:=jsonb_set(p_page,ARRAY[key],public._soe_circle_profile_message(p_circle_id,p_page->key)); END IF;
 END LOOP;
 RETURN p_page;
END
$body$$ddl$; COMMENT ON FUNCTION public._soe_circle_profile_page(uuid,jsonb) IS 'soe-circle-public-profiles:v1:owned'; END IF;
proc_oid:='public._soe_circle_profile_page(uuid,jsonb)'::regprocedure;
FOR grant_row IN SELECT DISTINCT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=proc_oid AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',proc_oid::regprocedure,CASE WHEN grant_row.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(grant_row.grantee)) END); END LOOP;
GRANT EXECUTE ON FUNCTION public._soe_circle_profile_page(uuid,jsonb) TO service_role;
IF to_regprocedure('public.soe_circle_detail_profiles(uuid,uuid)') IS NULL THEN EXECUTE $ddl$CREATE FUNCTION public.soe_circle_detail_profiles(p_actor uuid,p_circle_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $body$
DECLARE result jsonb; ref uuid;
BEGIN
 result:=public.soe_circle_detail(p_actor,p_circle_id);
 SELECT m.id INTO ref FROM public.book_cohorts c JOIN public.members m ON m.id=c.created_by AND m.profile_visibility='public'
  WHERE c.id=p_circle_id AND c.book_id='soe-circles-path' AND NOT c.circle_hidden;
 RETURN result || jsonb_build_object('publicProfileId',ref);
END
