IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.soe_circle_message_state_profiles(uuid,uuid,uuid)') AND md5(p.prosrc)='5a49a151dee0142e58cd7e0cd58ab89b' AND NOT p.prosecdef AND p.provolatile='v' AND p.prokind='f' AND p.prorettype='jsonb'::regtype AND p.pronargs=3 AND p.proargnames=ARRAY['p_actor','p_circle_id','p_message_id']::text[] AND NOT p.proretset AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u' AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargmodes IS NULL AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='sql') AND p.proconfig=ARRAY['search_path=pg_catalog, public']::text[] AND pg_get_userbyid(p.proowner)=current_user AND obj_description(p.oid,'pg_proc')='soe-circle-public-profiles:v1:owned') OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=to_regprocedure('public.soe_circle_message_state_profiles(uuid,uuid,uuid)') AND a.grantee NOT IN(p.proowner,(SELECT oid FROM pg_roles WHERE rolname='service_role'))) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Circle profile wrapper collision or drift requires review'; END IF;
IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('_soe_circle_profile_message','_soe_circle_profile_page','soe_circle_detail_profiles','soe_circle_messages_read_profiles','soe_circle_discussion_read_profiles','soe_circle_discussion_thread_profiles','soe_circle_discussion_receipt_profiles','soe_circle_message_state_profiles'))<>8 THEN RAISE EXCEPTION 'Profile wrapper overload requires review'; END IF;
END IF;
END $guard$;
